#!/usr/bin/env node
'use strict';
const { syncVersions } = require('./index.js');

const [, , root = '.'] = process.argv;
const changed = syncVersions(root);
console.log(changed.length ? `Synced ${changed.length} package(s).` : 'All versions already in sync.');

'use strict';
const { readFileSync, readdirSync, writeFileSync } = require('node:fs');
const { join } = require('node:path');

function syncVersions(root) {
  const rootManifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
  const changed = [];
  for (const dir of readdirSync(join(root, 'packages'))) {
    const file = join(root, 'packages', dir, 'package.json');
    const manifest = JSON.parse(readFileSync(file, 'utf8'));
    if (manifest.version === rootManifest.version) continue;
    manifest.version = rootManifest.version;
    writeFileSync(file, `${JSON.stringify(manifest, null, 2)}\n`);
    changed.push(manifest.name);
  }
  return changed;
}

module.exports = { syncVersions };

